import "server-only";
import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import type { GoogleProfile } from "better-auth/social-providers";
import { createRemoteJWKSet, jwtVerify } from "jose";
import { and, eq } from "drizzle-orm";
import { z } from "zod";
import { db } from "./db";
import * as schema from "./schema";
import { readWorkspaceProfile, validateIdentity, WorkspaceUnavailable } from "./workspace";

const googleKeys = createRemoteJWKSet(new URL("https://www.googleapis.com/oauth2/v3/certs"));
const config = z
  .object({
    BETTER_AUTH_URL: z.url(),
    BETTER_AUTH_SECRET: z.string().min(32),
    GOOGLE_CLIENT_ID: z.string().min(1),
    GOOGLE_CLIENT_SECRET: z.string().min(1),
    GOOGLE_WORKSPACE_DOMAIN: z.string().min(1),
  })
  .parse(process.env);

export const auth = betterAuth({
  appName: "Binden",
  baseURL: config.BETTER_AUTH_URL,
  secret: config.BETTER_AUTH_SECRET,
  database: drizzleAdapter(db, { provider: "pg", schema }),
  socialProviders: {
    google: {
      clientId: config.GOOGLE_CLIENT_ID,
      clientSecret: config.GOOGLE_CLIENT_SECRET,
      hd: config.GOOGLE_WORKSPACE_DOMAIN,
      scope: ["https://www.googleapis.com/auth/admin.directory.user.readonly"],
      accessType: "offline",
      prompt: "select_account consent",
      includeGrantedScopes: false,
      disableIdTokenSignIn: true,
      // The Google code-flow callback decodes by default. Verify before any
      // identity binding or session creation; state + PKCE bind this redirect.
      getUserInfo: async (tokens) => {
        try {
          if (!tokens.idToken || !tokens.accessToken) return null;
          const { payload } = await jwtVerify(tokens.idToken, googleKeys, {
            algorithms: ["RS256"],
            issuer: ["https://accounts.google.com", "accounts.google.com"],
            audience: config.GOOGLE_CLIENT_ID,
            requiredClaims: ["sub", "iat", "exp", "email", "email_verified", "hd"],
            maxTokenAge: "1h",
          });
          const identity = validateIdentity(payload);
          await readWorkspaceProfile(tokens.accessToken, identity.sub, true);
          return {
            // Better Auth requires an email/name. These are inert auth metadata,
            // not a second directory or a key based on a mutable Workspace email.
            user: { name: "", email: `${identity.sub}@google.invalid`, emailVerified: true },
            // Better Auth types optional Google profile claims as required;
            // its identity resolver uses only the validated immutable sub.
            data: { ...payload, ...identity } as GoogleProfile,
          };
        } catch {
          return null;
        }
      },
    },
  },
  account: {
    encryptOAuthTokens: true,
    storeStateStrategy: "database",
    accountLinking: { enabled: false, disableImplicitLinking: true },
  },
  session: { cookieCache: { enabled: false } },
  databaseHooks: {
    account: {
      create: { before: async (account) => ({ data: { ...account, idToken: null } }) },
      update: { before: async (account) => ({ data: { ...account, idToken: null } }) },
    },
  },
  onAPIError: { errorURL: "/?error=sign-in" },
});

export async function getOwnProfile(headers: Headers) {
  try {
    const session = await auth.api.getSession({ headers });
    if (!session) return { status: "signed-out" } as const;
    const [account] = await db
      .select()
      .from(schema.account)
      .where(
        and(eq(schema.account.userId, session.user.id), eq(schema.account.providerId, "google")),
      );
    if (!account) throw new WorkspaceUnavailable(true);
    let token;
    try {
      token = await auth.api.getAccessToken({ headers, body: { accountId: account.id } });
    } catch {
      throw new WorkspaceUnavailable(true);
    }
    if (
      !token.accessToken ||
      (token.accessTokenExpiresAt && new Date(token.accessTokenExpiresAt).getTime() <= Date.now())
    )
      throw new WorkspaceUnavailable(true);
    return {
      status: "available",
      profile: await readWorkspaceProfile(token.accessToken, account.accountId),
    } as const;
  } catch (error) {
    return {
      status:
        error instanceof WorkspaceUnavailable && error.reconnect ? "reconnect" : "unavailable",
    } as const;
  }
}

import "server-only";
import { eq } from "drizzle-orm";
import { z } from "zod";
import { db } from "./db";
import { workspaceIdentity } from "./schema";

const identitySchema = z.object({
  sub: z.string().min(1).max(255),
  hd: z.string().min(1),
  email: z.email(),
  email_verified: z.literal(true),
});
const profileSchema = z.object({
  id: z.string().min(1),
  primaryEmail: z.email(),
  name: z.object({ fullName: z.string() }).optional(),
  emails: z
    .array(
      z.object({
        address: z.email(),
        type: z.string().optional(),
        customType: z.string().optional(),
      }),
    )
    .optional(),
  phones: z
    .array(
      z.object({
        value: z.string(),
        type: z.string().optional(),
        customType: z.string().optional(),
      }),
    )
    .optional(),
});

export class WorkspaceUnavailable extends Error {
  constructor(public readonly reconnect = false) {
    super(reconnect ? "Reconnect your Google account" : "Workspace profile unavailable");
  }
}

export function validateIdentity(input: unknown) {
  const identity = identitySchema.parse(input);
  if (!process.env.GOOGLE_WORKSPACE_DOMAIN || identity.hd !== process.env.GOOGLE_WORKSPACE_DOMAIN)
    throw new WorkspaceUnavailable(true);
  return identity;
}

async function googleGet(url: string, accessToken: string) {
  const response = await fetch(url, {
    headers: { Authorization: `Bearer ${accessToken}` },
    cache: "no-store",
    signal: AbortSignal.timeout(10_000),
  });
  if (!response.ok)
    throw new WorkspaceUnavailable(response.status === 401 || response.status === 403);
  return response.json();
}

export async function readWorkspaceProfile(
  accessToken: string,
  subject: string,
  allowInitialBinding = false,
) {
  const identity = validateIdentity(
    await googleGet("https://openidconnect.googleapis.com/v1/userinfo", accessToken),
  );
  if (identity.sub !== subject) throw new WorkspaceUnavailable(true);
  const [binding] = await db
    .select()
    .from(workspaceIdentity)
    .where(eq(workspaceIdentity.googleSubject, subject));
  if (!binding && !allowInitialBinding) throw new WorkspaceUnavailable(true);
  const url = new URL(
    `https://admin.googleapis.com/admin/directory/v1/users/${encodeURIComponent(binding?.directoryId ?? identity.email)}`,
  );
  url.searchParams.set("viewType", "domain_public");
  url.searchParams.set(
    "fields",
    "id,primaryEmail,name(fullName),emails(address,type,customType),phones(value,type,customType)",
  );
  const profile = profileSchema.parse(await googleGet(url.toString(), accessToken));
  // Email is a fresh consistency check, never the durable identity key. During
  // rename propagation fail closed rather than resolving a different account.
  if (
    profile.primaryEmail.toLowerCase() !== identity.email.toLowerCase() ||
    (binding && profile.id !== binding.directoryId)
  )
    throw new WorkspaceUnavailable(true);
  if (!binding) {
    // Recheck the token's current owner before establishing the first binding.
    const current = validateIdentity(
      await googleGet("https://openidconnect.googleapis.com/v1/userinfo", accessToken),
    );
    if (
      current.sub !== subject ||
      current.email.toLowerCase() !== profile.primaryEmail.toLowerCase()
    )
      throw new WorkspaceUnavailable(true);
    await db
      .insert(workspaceIdentity)
      .values({ googleSubject: subject, directoryId: profile.id })
      .onConflictDoNothing();
    const [saved] = await db
      .select()
      .from(workspaceIdentity)
      .where(eq(workspaceIdentity.googleSubject, subject));
    if (saved?.directoryId !== profile.id) throw new WorkspaceUnavailable(true);
  }
  return profile;
}

import { boolean, index, pgTable, text, timestamp, uniqueIndex } from "drizzle-orm/pg-core";

export const user = pgTable("auth_user", {
  id: text().primaryKey(),
  name: text().notNull(),
  email: text().notNull().unique(),
  emailVerified: boolean("email_verified").notNull(),
  image: text(),
  createdAt: timestamp("created_at").notNull(),
  updatedAt: timestamp("updated_at").notNull(),
});

export const session = pgTable(
  "auth_session",
  {
    id: text().primaryKey(),
    expiresAt: timestamp("expires_at").notNull(),
    token: text().notNull().unique(),
    createdAt: timestamp("created_at").notNull(),
    updatedAt: timestamp("updated_at").notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [index("session_user_idx").on(table.userId)],
);

export const account = pgTable(
  "auth_account",
  {
    id: text().primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at"),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
    scope: text(),
    password: text(),
    createdAt: timestamp("created_at").notNull(),
    updatedAt: timestamp("updated_at").notNull(),
  },
  (table) => [
    index("account_user_idx").on(table.userId),
    uniqueIndex("account_provider_subject_idx").on(table.providerId, table.accountId),
  ],
);

export const verification = pgTable(
  "auth_verification",
  {
    id: text().primaryKey(),
    identifier: text().notNull(),
    value: text().notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").notNull(),
    updatedAt: timestamp("updated_at").notNull(),
  },
  (table) => [uniqueIndex("verification_identifier_idx").on(table.identifier)],
);

// Identity binding only: neither mutable profile data nor application roles.
export const workspaceIdentity = pgTable("workspace_identity", {
  googleSubject: text("google_subject").primaryKey(),
  directoryId: text("directory_id").notNull().unique(),
});

import { auth } from "@/lib/auth";
import { z } from "zod";

const signInBody = z.strictObject({
  provider: z.literal("google"),
  callbackURL: z.string().optional(),
  errorCallbackURL: z.string().optional(),
});

// Only the browser journey is public. Better Auth's token-returning and account
// management APIs remain available solely through trusted server-side calls.
async function handle(request: Request) {
  const path = new URL(request.url).pathname;
  const allowed =
    request.method === "GET"
      ? path === "/api/auth/callback/google"
      : request.method === "POST" &&
        ["/api/auth/sign-in/social", "/api/auth/sign-out"].includes(path);
  if (!allowed) return new Response(null, { status: 404 });
  if (
    request.method === "POST" &&
    request.headers.get("origin") !== new URL(process.env.BETTER_AUTH_URL!).origin
  )
    return new Response(null, { status: 403 });
  if (path === "/api/auth/sign-in/social") {
    try {
      signInBody.parse(await request.clone().json());
    } catch {
      return new Response(null, { status: 400 });
    }
  }
  const response = await auth.handler(request);
  response.headers.set("Cache-Control", "no-store");
  return response;
}

export const GET = handle;
export const POST = handle;
import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { getOwnProfile } from "@/lib/auth";
import { AuthButton } from "@/components/auth-button";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

export default async function Profile() {
  const result = await getOwnProfile(await headers());
  if (result.status === "signed-out") redirect("/");
  return (
    <main className="mx-auto w-full max-w-2xl p-6 sm:py-16">
      {result.status === "available" ? (
        <Card>
          <CardHeader>
            <CardTitle className="text-3xl font-semibold tracking-tight">
              <h1>Your Workspace profile</h1>
            </CardTitle>
            <CardDescription>Current shared information from Google Workspace.</CardDescription>
            <CardAction>
              <Badge variant="secondary">Current from Google Workspace</Badge>
            </CardAction>
          </CardHeader>
          <CardContent>
            <dl className="flex flex-col gap-5">
              <div className="flex flex-col gap-1">
                <dt className="font-medium">Name</dt>
                <dd>{result.profile.name?.fullName ?? "Unavailable"}</dd>
              </div>
              <div className="flex flex-col gap-1">
                <dt className="font-medium">Workspace email</dt>
                <dd className="break-all">{result.profile.primaryEmail}</dd>
              </div>
              <div className="flex flex-col gap-1">
                <dt className="font-medium">Contact emails</dt>
                <dd>
                  {result.profile.emails === undefined ? (
                    "Unavailable"
                  ) : result.profile.emails.length === 0 ? (
                    "No shared entries"
                  ) : (
                    <ul>
                      {result.profile.emails.map((entry, index) => (
                        <li key={index} className="break-all">
                          {entry.address}
                        </li>
                      ))}
                    </ul>
                  )}
                </dd>
              </div>
              <div className="flex flex-col gap-1">
                <dt className="font-medium">Phones</dt>
                <dd>
                  {result.profile.phones === undefined ? (
                    "Unavailable"
                  ) : result.profile.phones.length === 0 ? (
                    "No shared entries"
                  ) : (
                    <ul>
                      {result.profile.phones.map((entry, index) => (
                        <li key={index}>{entry.value}</li>
                      ))}
                    </ul>
                  )}
                </dd>
              </div>
            </dl>
          </CardContent>
          <CardFooter>
            <AuthButton action="sign-out" />
          </CardFooter>
        </Card>
      ) : (
        <Card role="alert">
          <CardHeader>
            <CardTitle className="text-3xl font-semibold tracking-tight">
              <h1>
                {result.status === "reconnect"
                  ? "Reconnect your Google account"
                  : "Workspace profile unavailable"}
              </h1>
            </CardTitle>
            <CardDescription>
              {result.status === "reconnect"
                ? "Your Google connection needs to be renewed."
                : "Google Workspace could not provide your current profile."}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <p className="text-muted-foreground">
              {result.status === "reconnect"
                ? "Google rejected your connection or could not confirm your identity. Reconnect with your managed account."
                : "Your current profile could not be retrieved. It may be hidden or unavailable, or Google may be temporarily unreachable."}
            </p>
          </CardContent>
          <CardFooter className="gap-2">
            {result.status === "reconnect" ? (
              <AuthButton action="reconnect" />
            ) : (
              <form action="/profile" method="get">
                <Button type="submit">Try again</Button>
              </form>
            )}
            <AuthButton action="sign-out" />
          </CardFooter>
        </Card>
      )}
    </main>
  );
}

